// HYDRA standard library v1.1 — extension parts. Same drawing rules as the Home library:
// Symbol Sketcher entity format (mm, y-up, origin at the symbol centre), ISO 1219-1 for fluid power, IEC 60617 for electrical.
// Every part here is a different function or a different look; nothing repeats an existing part.
import type { Ent, Port, Spec, StdItem } from './symbols';

let k = 0; const base = (o: any): Ent => ({ id: 'sx' + (k++), layer: 'L0', group: null, stroke: null, line_type: null, color: null, hidden: false, locked: false, ...o });
const L = (x1: number, y1: number, x2: number, y2: number, o: any = {}) => base({ type: 'line', x1, y1, x2, y2, ...o });
const C = (cx: number, cy: number, r: number, o: any = {}) => base({ type: 'circle', cx, cy, r, ...o });
const A = (cx: number, cy: number, r: number, a0: number, a1: number, o: any = {}) => base({ type: 'arc', cx, cy, r, a0, a1, ...o });
const R = (x: number, y: number, w: number, h: number, o: any = {}) => base({ type: 'rect', x, y, w, h, ...o });
const P = (pts: number[][], closed = true, o: any = {}) => base({ type: 'poly', pts, closed, ...o });
const T = (x: number, y: number, s: string, h = 4, o: any = {}) => base({ type: 'text', x, y, s, h, ...o });
const D = { line_type: 'dashed' }, F = { fill: true }, CH = { line_type: 'chain' };
const pl = (pts: number[][], o: any = {}) => P(pts, false, o);
const port = (name: string, x: number, y: number, or: number, domain: string, role = 'work', dir = 'bi'): Port => ({ name, x, y, or, role, domain, dir });
const head = (x: number, y: number, a: number, s = 2.4, fill = true) => { const r = a * Math.PI / 180, c = Math.cos(r), si = Math.sin(r), bx = x - c * s, by = y - si * s, w = s * 0.38; return P([[x, y], [bx - si * w, by + c * w], [bx + si * w, by - c * w]], true, fill ? F : {}); };
const arrow = (x1: number, y1: number, x2: number, y2: number, o: any = {}, s = 2.4) => [L(x1, y1, x2, y2, o), head(x2, y2, Math.atan2(y2 - y1, x2 - x1) * 180 / Math.PI, s)];
const arrow2 = (x1: number, y1: number, x2: number, y2: number) => { const a = Math.atan2(y2 - y1, x2 - x1) * 180 / Math.PI; return [L(x1, y1, x2, y2), head(x2, y2, a), head(x1, y1, a + 180)]; };
const zig = (x1: number, y1: number, x2: number, y2: number, amp = 2.4, n = 3) => { const pts: number[][] = [[x1, y1]]; const dx = x2 - x1, dy = y2 - y1, l = Math.hypot(dx, dy), ux = dx / l, uy = dy / l; for (let i = 0; i < n * 2; i++) { const t = (i + 0.5) / (n * 2), s = i % 2 ? -amp : amp; pts.push([x1 + dx * t - uy * s, y1 + dy * t + ux * s]); } pts.push([x2, y2]); return pl(pts); };
const spring = (x: number, y: number, len = 9, adj = true, amp = 2.4) => [zig(x, y, x + len, y, amp, 3), ...(adj ? arrow(x + 1, y - 5, x + len, y + 5) : [])];
const propSol = (x: number, y: number) => [R(x, y - 3.5, 5, 7), L(x, y - 3.5, x + 5, y + 3.5), ...arrow(x - 1.5, y - 5.5, x + 6.5, y + 5.5, {}, 2)];
const solenoid = (x: number, y: number) => [R(x, y - 3.5, 5, 7), L(x, y - 3.5, x + 5, y + 3.5)];
const tri = (x: number, y: number, up: boolean, fill: boolean, s = 3.2) => P(up ? [[x - s / 2, y], [x + s / 2, y], [x, y + s * 0.9]] : [[x - s / 2, y], [x + s / 2, y], [x, y - s * 0.9]], true, fill ? F : {});
// ball-seat check element on a vertical line at x, free flow upward from yb to yt
// free flow from y=from to y=to (either direction)
const checkV = (x: number, from: number, to: number, r = 2.4) => { const s = Math.sign(to - from) || 1, ym = (from + to) / 2, ap = ym - 2.6 * s; return [L(x, from, x, ap), L(x - 4, ym + 1.4 * s, x, ap), L(x, ap, x + 4, ym + 1.4 * s), C(x, ym + 1.2 * s, r), L(x, ym + (1.2 + r) * s, x, to)]; };
const checkVspring = (x: number, from: number, to: number) => { const s = Math.sign(to - from) || 1, ym = (from + to) / 2; return [...checkV(x, from, to, 2.2), zig(x + 2.6, ym + 2.6 * s, x + 6.5, ym + 6 * s, 1.1, 2)]; };
const throttle = (x: number, y: number, adj = false) => [A(x - 7, y, 5, 315, 45), A(x + 7, y, 5, 135, 225), ...(adj ? arrow(x - 6, y - 6, x + 6, y + 6) : [])];
const enclose = (x: number, y: number, w: number, h: number) => R(x, y, w, h, CH);
const leadsV = (h = 8, len = 8) => [L(0, -h, 0, -h - len), L(0, h, 0, h + len)];

// ---------------- pressure valve builder (box centred at ox,0, half-size hb) ----------------
type PV = { ox?: number; hb?: number; open?: boolean; down?: boolean; pilot?: 'in' | 'out' | 'ext' | 'none'; spring?: 'adj' | 'fixed' | 'prop'; drain?: boolean; leads?: boolean };
function pvalve(o: PV) {
  const ox = o.ox ?? 0, hb = o.hb ?? 8, e: Ent[] = [R(ox - hb, -hb, 2 * hb, 2 * hb)];
  const ax = o.open ? ox : ox - hb * 0.45; e.push(...(o.down ? arrow(ax, hb * 0.75, ax, -hb * 0.75) : arrow(ax, -hb * 0.75, ax, hb * 0.75)));
  if (o.spring === 'prop') e.push(zig(ox + hb, 0, ox + hb + 4, 0, 1.8, 2), ...propSol(ox + hb + 4, 0));
  else e.push(...spring(ox + hb, 0, 9, o.spring !== 'fixed'));
  const px = ox - hb - 6;
  if (o.pilot === 'in') e.push(pl([[ox, -hb - 4], [px, -hb - 4], [px, 0], [ox - hb, 0]], D));
  if (o.pilot === 'out') e.push(pl([[ox, hb + 4], [px, hb + 4], [px, 0], [ox - hb, 0]], D));
  if (o.pilot === 'ext') e.push(L(ox - hb, 0, ox - hb - 8, 0, D));
  if (o.drain) e.push(pl([[ox + hb - 2, -hb], [ox + hb - 2, -hb - 8]], D));
  if (o.leads !== false) e.push(L(ox, -hb, ox, -hb - 8), L(ox, hb, ox, hb + 8));
  return e;
}
const PR = 'Pressure and flow are set per circuit instance';
const sp = (key: string, label: string, value: any, qty: any = 'none', unit?: string): Spec => ({ key, label, qty, value, unit });
const H = 'hydraulic', PN = 'pneumatic', E = 'electrical';
const item = (id: string, name: string, domain: any, category: string, cls: string, ents: Ent[], ports: Port[], specs: Spec[] = [], tags: string[] = [], template = 'passive', note?: string): StdItem =>
  ({ id, name, domain, category, cls, standard: domain === E ? 'IEC 60617' : 'ISO 1219-1', tags, template, ents, ports, specs, note });
const PC = 'Pressure control', NF = 'Non-return & flow', PM = 'Pumps & motors', CY = 'Cylinders & actuators', CM = 'Conditioning & measurement', LC = 'Lines & connections', PS = 'Supply, air preparation & logic', PA = 'Actuators';
const pIO = (d = H, a = 'P', b = 'T', ra = 'supply', rb = 'return') => [port(a, 0, -16, 270, d, ra, 'in'), port(b, 0, 16, 90, d, rb, 'out')];

